/bin/bash -lc "cd [workspace path] && python3 << 'EOF'
import numpy as np
from PIL import Image
im = np.array(Image.open('first_frame.png').convert('RGB'))
R,G,B = im[...,0].astype(int), im[...,1].astype(int), im[...,2].astype(int)
green = (G>110)&(R<90)&(B<90)
ys,xs = np.where(green)
pts = np.column_stack([xs,ys])
# convex hull (monotone chain)
def hull(p):
    p = np.unique(p,axis=0)
    p = p[np.lexsort((p[:,0],p[:,1]))]
    def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
    lo=[]
    for q in p:
        while len(lo)>=2 and cross(lo[-2],lo[-1],q)<=0: lo.pop()
        lo.append(tuple(q))
    hi=[]
    for q in p[::-1]:
        while len(hi)>=2 and cross(hi[-2],hi[-1],q)<=0: hi.pop()
        hi.append(tuple(q))
    return np.array(lo[:-1]+hi[:-1])
H = hull(pts)
print(\"hull vertices:\", len(H))
print(H.tolist())
# simplify with distance tolerance
def simplify(poly, tol):
    out=[poly[0]]
    for i in range(1,len(poly)):
        if np.hypot(*(poly[i]-out[-1]))>tol: out.append(poly[i])
    return np.array(out)
S=simplify(H,6)
print(\"simplified:\",S.tolist())
EOF"
